local B=""
local A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local M={}
for i=1,#A do M[string.byte(A,i)]=i-1 end
local R={}
local ri=0
for i=1,#B,4 do
 local a=M[string.byte(B,i)] or 0
 local b=M[string.byte(B,i+1)] or 0
 local c=M[string.byte(B,i+2)]
 local d=M[string.byte(B,i+3)]
 ri=ri+1 R[ri]=string.char(a*4+math.floor(b/16))
 if c then
  ri=ri+1 R[ri]=string.char((b%16)*16+math.floor(c/4))
  if d then
   ri=ri+1 R[ri]=string.char((c%4)*64+d)
  end
 end
end
local P=table.concat(R)
local D={}
for i=0,255 do D[i]=string.char(i) end
local function G(i)
 local a,b=string.byte(P,i,i+1)
 return a+b*256
end
local O={}
local k=1
local old=G(k)
k=k+2
local w=D[old]
O[1]=w
local n=256
while k<=#P do
 local cur=G(k)
 k=k+2
 local e=D[cur]
 if not e then
  if cur==n then e=w..string.sub(w,1,1) else error("NEXUS packed source is corrupt") end
 end
 O[#O+1]=e
 if n<65536 then
  D[n]=w..string.sub(e,1,1)
  n=n+1
 end
 w=e
end
local S=table.concat(O)
local F,E=loadstring(S)
if not F then error(E) end
return F()
